mapper.select:

WHERE 1 = 1

    AND w.worker_id = #{workerId}


    AND w.status = #{status}

ORDER BY w.time_slot, w.id

SELECT COUNT(*) FROM work_order w
WHERE w.time_slot LIKE #{prefix}
  AND w.status IN ('ASSIGNED', 'INSTALLING')

    AND w.worker_id = #{workerId}

SELECT COUNT(*) FROM work_order w
WHERE w.status = 'DONE' AND DATE(w.complete_time) = #{day}

    AND w.worker_id = #{workerId}

SELECT w.time_slot AS timeSlot, COUNT(*) AS c FROM work_order w
WHERE w.time_slot LIKE #{prefix}

    AND w.worker_id = #{workerId}

GROUP BY w.time_slot

SELECT w.time_slot AS timeSlot, COUNT(*) AS c FROM work_order w
WHERE w.time_slot >= #{from}

    AND w.worker_id = #{workerId}

GROUP BY w.time_slot
